import { useEffect, useState, useCallback } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import policyAction from '../../../redux/policy/actions'
import { useRouteMatch, useHistory } from 'react-router'
import CircularLoader from '../../../components/CircularLoader'
import { PERSONAL_ACCIDENT_BILLER_ASSETS } from '../constants'
import {
  Wrapper,
  FormArea,
  FormCard,
  FormTop,
  Illustration,
  FormTitle,
  FormSubtitle,
  FormBody,
  InputWrapper,
  PhoneField,
  PhoneInput,
  FieldMessage,
  SubmitButton,
  SubmitButtonText,
  SuccessTitle,
  SuccessMessage,
  ErrorTitle,
  ErrorMessage,
  RedirectSection,
  RedirectText,
  RedirectLink,
  FooterIllustration,
  FooterSection,
  FooterText,
  PolicyDetailCard,
  PolicyDetailTop,
  PolicyDetailInfo,
  PolicyDetailIllustration,
  PolicyDetailContent,
  PolicyDetailText,
  PolicyDetailButton,
  PolicyDetailButtonText
} from './index.style'

const { tokenizedDetailEndorsement, authorisedEndorsement } = policyAction

function PersonalAccidentBillerEndorsement(props) {
  const router = useRouteMatch()
  const history = useHistory()
  const {
    getPolicyEndorsementDetailResult,
    policyEndorsementDetailLoading,
    policyEndorsementLoading,
    policyEndorsement,
    policyEndorsementMessage
  } = props

  const [phoneNumber, setPhoneNumber] = useState('')
  const [confirmPhone, setConfirmPhone] = useState('')
  const [formState, setFormState] = useState('idle')
  const [submittedPhone, setSubmittedPhone] = useState('')
  const [dotCount, setDotCount] = useState(1)
  const [errorMessage, setErrorMessage] = useState('')
  const [hasAttemptedDetail, setHasAttemptedDetail] = useState(false)

  const isMatch = confirmPhone.length > 0 && confirmPhone === phoneNumber
  const isMismatch = confirmPhone.length > 0 && confirmPhone !== phoneNumber
  const showMessage = isMatch || isMismatch
  const isButtonDisabled = !isMatch || formState === 'success'
  const redirectCount = 10 * 1000

  const handlePhoneChange = useCallback((e) => {
    const value = e.target.value.replace(/\D/g, '')
    setPhoneNumber(value)
  }, [])

  const handleConfirmChange = useCallback((e) => {
    const value = e.target.value.replace(/\D/g, '')
    setConfirmPhone(value)
  }, [])

  const handleSubmit = useCallback(() => {
    if (!isMatch) return
    const { internal_id, token } = router.params
    setFormState('loading')
    props.authorisedEndorsement({
      query: {
        internal_id,
        token
      },
      body: {
        phone_no: phoneNumber
      }
    })
  }, [isMatch, router.params, phoneNumber])

  const getRequestData = useCallback(() => {
    const { internal_id, token } = router.params
    props.tokenizedDetailEndorsement({
      query: {
        id: internal_id,
        token
      }
    })
  }, [router.params])

  useEffect(() => {
    if (router?.params) {
      getRequestData()
    }
  }, [])

  useEffect(() => {
    if (policyEndorsementDetailLoading === true) {
      setHasAttemptedDetail(true)
    }
  }, [policyEndorsementDetailLoading])

  useEffect(() => {
    if (
      hasAttemptedDetail &&
      !policyEndorsementDetailLoading &&
      (!getPolicyEndorsementDetailResult ||
        Object.keys(getPolicyEndorsementDetailResult).length === 0)
    ) {
      setErrorMessage('Gagal memuat data polis. Silakan muat ulang halaman.')
      setFormState('error')
    }
  }, [
    hasAttemptedDetail,
    policyEndorsementDetailLoading,
    getPolicyEndorsementDetailResult
  ])

  useEffect(() => {
    if (
      getPolicyEndorsementDetailResult &&
      Object.keys(getPolicyEndorsementDetailResult).length > 0
    ) {
      const endorsement =
        getPolicyEndorsementDetailResult?.endorsement
      const requestData =
        getPolicyEndorsementDetailResult?.Request

      if (endorsement && Object.keys(endorsement)?.length > 0) {
        const phone = endorsement?.phone_no || endorsement?.phone_number || ''
        setSubmittedPhone(phone || '')
        setFormState('success')
      }
    }
  }, [getPolicyEndorsementDetailResult])

  useEffect(() => {
    if (formState === 'success') {
      const interval = setInterval(() => {
        setDotCount((prev) => (prev % 3) + 1)
      }, 500)
      const timer = setTimeout(() => {
        window.location.href = 'https://mkp.ppibroker.com/login'
      }, redirectCount)
      return () => {
        clearInterval(interval)
        clearTimeout(timer)
      }
    }
  }, [formState])

  useEffect(() => {
    if (!policyEndorsementLoading && formState === 'loading') {
      const isSuccess = policyEndorsementMessage === 'success'
      if (isSuccess) {
        setSubmittedPhone(phoneNumber)
        setFormState('success')
      } else {
        setErrorMessage('Gagal menyimpan nomor ponsel. Silakan coba lagi.')
        setFormState('submitError')
      }
    }
  }, [policyEndorsementLoading, policyEndorsementMessage])

  const formatPhoneDisplay = (phone) => {
    if (!phone) return ''
    const cleaned = phone.replace(/\D/g, '')
    if (cleaned.length <= 4) return cleaned
    if (cleaned.length <= 8) {
      return `${cleaned.slice(0, 4)}-${cleaned.slice(4)}`
    }
    return `${cleaned.slice(0, 4)}-${cleaned.slice(4, 8)}-${cleaned.slice(8)}`
  }

  const isLoading =
    !!policyEndorsementDetailLoading || !!policyEndorsementLoading

  const renderForm = () => (
    <FormCard>
      <FormTop>
        <Illustration src={PERSONAL_ACCIDENT_BILLER_ASSETS.formIllustration} alt="" />
        <FormTitle>Lengkapi Data Pelanggan</FormTitle>
        {formState === 'submitError' ? (
          <ErrorMessage>{errorMessage}</ErrorMessage>
        ) : (
          <FormSubtitle>
            Masukkan nomor ponsel untuk kelengkapan data pelanggan dan
            dibutuhkan untuk pengiriman OTP dalam proses pengajuan dan
            verifikasi klaim.
          </FormSubtitle>
        )}
      </FormTop>
      <FormBody>
        <InputWrapper>
          <PhoneField>
            <PhoneInput
              placeholder="08XX-XXXX-XXXX"
              value={phoneNumber ? formatPhoneDisplay(phoneNumber) : ''}
              onChange={handlePhoneChange}
              $isEmpty={!phoneNumber}
            />
          </PhoneField>
        </InputWrapper>
        <InputWrapper>
          <PhoneField $hasError={isMismatch} $isMatch={isMatch}>
            <PhoneInput
              placeholder="Tulis Ulang Nomor Ponsel"
              value={confirmPhone ? formatPhoneDisplay(confirmPhone) : ''}
              onChange={handleConfirmChange}
              $isEmpty={!confirmPhone}
            />
          </PhoneField>
          {showMessage && (
            <FieldMessage $isError={isMismatch}>
              {isMismatch
                ? 'Nomor ponsel yang dimasukkan tidak sama'
                : 'Nomor ponsel sudah sama'}
            </FieldMessage>
          )}
        </InputWrapper>
        <SubmitButton
          $disabled={isButtonDisabled}
          disabled={isButtonDisabled}
          onClick={handleSubmit}
        >
          <SubmitButtonText $disabled={isButtonDisabled}>
            Simpan
          </SubmitButtonText>
        </SubmitButton>
      </FormBody>
    </FormCard>
  )

  const renderSuccess = () => (
    <FormCard>
      <FormTop>
        <Illustration src={PERSONAL_ACCIDENT_BILLER_ASSETS.formIllustrationDone} alt="" />
        <SuccessTitle>Data Telah Tersimpan</SuccessTitle>
        <SuccessMessage>
          Nomor ponsel {formatPhoneDisplay(submittedPhone)} berhasil disimpan
          dan Anda akan diarahkan secara otomatis ke Portal Klaim PasarPolis
          Indonesia Broker.
          <br />
          <br />
          <span style={{ color: '#0078FA' }}>Mengarahkan{'.'.repeat(dotCount)}</span>
        </SuccessMessage>
      </FormTop>
      <RedirectSection>
        <RedirectText>
          Klik tautan di bawah jika tidak pindah secara otomatis.
        </RedirectText>
        <RedirectLink
          href="https://mkp.ppibroker.com/login"
          target="_blank"
          rel="noopener noreferrer"
        >
          https://mkp.ppibroker.com/login
        </RedirectLink>
      </RedirectSection>
    </FormCard>
  )

  const renderError = () => (
    <FormCard>
      <FormTop>
        <Illustration src={PERSONAL_ACCIDENT_BILLER_ASSETS.formIllustration} alt="" />
        <ErrorTitle>Terjadi Kesalahan</ErrorTitle>
        <ErrorMessage>
          {errorMessage}
        </ErrorMessage>
      </FormTop>
    </FormCard>
  )

  const renderPolicyDetail = () => {
    const documentUrl = getPolicyEndorsementDetailResult?.DocumentURL
    const isButtonDisabled = !documentUrl || documentUrl === 'NA'

    return (
      <PolicyDetailCard>
        <PolicyDetailTop>
          <PolicyDetailInfo>
            <PolicyDetailIllustration src={PERSONAL_ACCIDENT_BILLER_ASSETS.formIllustration} alt="" />
            <PolicyDetailContent>
              <PolicyDetailText>
                Pelajari produk asuransi Anda, cara pengajuan klaim dan cek
                manfaat apa saja yang Anda dapatkan.
              </PolicyDetailText>
            </PolicyDetailContent>
          </PolicyDetailInfo>
          <PolicyDetailButton
            href={isButtonDisabled ? undefined : documentUrl}
            target="_blank"
            rel="noopener noreferrer"
            $disabled={isButtonDisabled}
          >
            <PolicyDetailButtonText $disabled={isButtonDisabled}>
              Lihat Detail Polis
            </PolicyDetailButtonText>
          </PolicyDetailButton>
        </PolicyDetailTop>
      </PolicyDetailCard>
    )
  }

  return (
    <Wrapper>
      <FormArea>
        <CircularLoader isSpining={isLoading}>
          {formState === 'success'
            ? renderSuccess()
            : formState === 'error'
              ? renderError()
              : renderForm()}
        </CircularLoader>
        {renderPolicyDetail()}
      </FormArea>
      <FooterIllustration src={PERSONAL_ACCIDENT_BILLER_ASSETS.footerIllustration} alt="" />
      <FooterSection>
        <FooterText>
          PT PasarPolis Insurance Broker (PPIB) berizin dan diawasi oleh
          Otoritas Jasa Keuangan (OJK).
        </FooterText>
      </FooterSection>
    </Wrapper>
  )
}

export default connect(
  (state) => ({
    getPolicyEndorsementDetailResult:
      state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading:
      state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError:
      state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage:
      state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT
  }),
  {
    authorisedEndorsement,
    tokenizedDetailEndorsement
  }
)(injectIntl(PersonalAccidentBillerEndorsement))
